    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Recipient</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.RecipientName</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(shipment)">Edit</button>
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => DeleteShipment(shipment.Id)">Delete</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto? editingShipment;
    private bool showForm;
    private string? errorMessage;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            (s.RecipientName?.Contains(filterText, StringComparison.OrdinalIgnoreCase) ?? false)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
            errorMessage = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto
        {
            TrackingNumber = $"TRK-{Random.Shared.Next(100000, 999999)}",
            ShippedDate = DateTime.UtcNow,
            EstimatedDelivery = DateTime.UtcNow.AddDays(5)
        };
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            RecipientName = shipment.RecipientName,
            RecipientEmail = shipment.RecipientEmail,
            Notes = shipment.Notes
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        try
        {
            if (editingShipment!.Id > 0)
                await ShipmentService.UpdateShipmentAsync(editingShipment);
            else
                await ShipmentService.CreateShipmentAsync(editingShipment);

            showForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save shipment: {ex.Message}";
        }
    }

    private async Task DeleteShipment(int id)
    {
        try
        {
            await ShipmentService.DeleteShipmentAsync(id);
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to delete shipment: {ex.Message}";
        }
    }

    private void CancelForm() => showForm = false;

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject ShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p class="text-muted">Enter your tracking number to check shipment status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. TRK-100001"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not Found.</strong> No shipment found with tracking number "<strong>@searchedNumber</strong>".
        Please verify the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header bg-primary text-white">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h6>Shipment Details</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7">
                            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@GetStatusDisplay(shipment.Status)</span>
                        </dd>
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>
                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <h6>Delivery Information</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Shipped Date</dt>
                        <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">
                            <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                            @if (shipment.Status != ShipmentStatus.Delivered)
                            {
                                var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                <br />
                                <small class="text-muted">
                                    @if (daysLeft > 0)
                                    {
                                        @($"({daysLeft} day{(daysLeft != 1 ? "s" : "")} remaining)")
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        @("(Expected today)")
                                    }
                                    else
                                    {
                                        @($"({Math.Abs(daysLeft)} day{(Math.Abs(daysLeft) != 1 ? "s" : "")} overdue)")
                                    }
                                </small>
                            }
                        </dd>
                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@shipment.RecipientName</dd>
                    </dl>
                </div>
            </div>

            <!-- Progress indicator -->
            <div class="mt-4">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(shipment.Status)%"
                         aria-valuenow="@GetProgressPercentage(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @GetStatusDisplay(shipment.Status)
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1">
                    <small>Pending</small>
                    <small>Picked Up</small>
                    <small>In Transit</small>
                    <small>Out for Delivery</small>
                    <small>Delivered</small>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string? searchedNumber;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isLoading = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingAsync(searchedNumber);
            if (shipment is null)
                notFound = true;
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusDisplay(ShipmentStatus status) => status switch
    {
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Returned => 25,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger progress-bar-striped progress-bar-animated",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

